function barcodeSVG(seed,w,h){
 let x=0,s=seed,out='';const bars=[];
 const rnd=()=>{s=(s*9301+49297)%233280;return s/233280};
 bars.push([0,2],[3,1]);x=5;
 while(x<w-8){const bw=1+Math.floor(rnd()*3.2);bars.push([x,bw]);x+=bw+1+Math.floor(rnd()*2.4)}
 bars.push([w-5,1],[w-3,2]);
 out=bars.map(([bx,bw])=>`<rect x="${bx}" y="0" width="${bw}" height="${h}"/>`).join('');
 return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">${out}</svg>`;
}
