/* Responsive shell:
   Keep every prototype coordinate in the original 390x844 design space.
   Different phones scale the whole stage uniformly instead of reflowing px-based overlays. */
let stableViewportHeight=0;
function syncPrototypeViewport(){
  const vv=window.visualViewport;
  const vw=Math.max(1, vv ? vv.width : window.innerWidth);
  const rawVh=Math.max(1, vv ? vv.height : window.innerHeight);
  const mobile=window.matchMedia('(max-width: 600px), (pointer: coarse)').matches;
  const editing=/^(INPUT|TEXTAREA)$/.test(document.activeElement?.tagName||'');

  // Keep the app from suddenly shrinking when the mobile keyboard opens.
  if(!editing || !stableViewportHeight) stableViewportHeight=rawVh;
  let vh=editing ? Math.max(rawVh,stableViewportHeight) : rawVh;

  const horizontalPad=mobile ? 0 : 16;
  const verticalPad=mobile ? 0 : 52; // room for desktop debug controls
  const availableW=Math.max(1, vw-horizontalPad*2);
  const availableH=Math.max(1, vh-verticalPad);

  /* APPFILL: on phones the app fills the whole screen; the fake status bar (top 47px) is cropped
     because the device shows its own. Slight aspect differences are absorbed by a tiny vertical stretch. */
  const R=document.documentElement.style;let sx,sy,tx=0,ty=0,cut=0;
  window.__gapTop=0;
  let sb=0;
  if(mobile){const pr=document.getElementById('sa-probe')||(()=>{const d=document.createElement('div');d.id='sa-probe';d.style.cssText='position:fixed;left:0;bottom:0;width:0;height:env(safe-area-inset-bottom,0px);visibility:hidden;pointer-events:none';document.body.appendChild(d);return d})();sb=pr.offsetHeight||0}
  document.documentElement.style.setProperty('--sb',sb+'px');
  if(mobile){
    /* the 390x844 design already includes the home-indicator zone (80px tab bar), so no extra strip is reserved */
    cut=47;const dh=H-cut;sx=vw/W;const need=vh/sx;
    if(need>=dh){sy=sx;ty=vh-dh*sx;window.__gapTop=ty}
    else if(need>=dh*0.95){sy=vh/dh}
    else{const s=vh/dh;sx=sy=s;tx=(vw-W*s)/2}
  }else{
    let s=Math.min(availableW/W, availableH/H,1);s=Math.max(.35,s);sx=sy=s;tx=(vw-W*s)/2;ty=Math.max(0,(vh-verticalPad-H*s)/2);
  }
  window.__sx=sx;window.__sy=sy;
  R.setProperty('--sx',String(sx));R.setProperty('--sy',String(sy));
  R.setProperty('--tx',tx+'px');R.setProperty('--cut',cut+'px');R.setProperty('--ty',(ty-cut*sy)+'px');
  R.setProperty('--app-scale',String(Math.min(sx,sy)));
  document.documentElement.classList.toggle('app-fill',mobile);
  document.documentElement.style.setProperty('--viewport-w',`${vw}px`);
  document.documentElement.style.setProperty('--viewport-h',`${vh}px`);
  document.documentElement.classList.toggle('is-mobile-shell',mobile);
}
