function bindPressMotion(){
  const selector='.sheet-activity,.sheet-route,.sheet-route-qr,.nav-hit,.carbon17-arrow,.carbon17-marker-hit,.team-chat-hit,.esg-heart,.esg-propose-fixed,.coupon-tab-hit,.coupon-points-hit,.points-back-hit,.modal-btn,.qr-close,.guide-close-hit,.team-member-praise,.team-member-nag,.onboard-hit,.skip-hit,.carbon-home-button';
  const release=el=>{
    if(!el)return;
    el.classList.remove('is-pressed');
    el.classList.add('was-pressed');
    setTimeout(()=>el.classList.remove('was-pressed'),170);
  };
  phone.addEventListener('pointerdown',e=>{
    const el=e.target.closest?.(selector); if(!el)return;
    el.classList.add('is-pressed');
  },{passive:true});
  phone.addEventListener('pointerup',e=>release(e.target.closest?.(selector)),{passive:true});
  phone.addEventListener('pointercancel',e=>release(e.target.closest?.(selector)),{passive:true});
  phone.addEventListener('pointerleave',e=>release(e.target.closest?.(selector)),{passive:true});
}
