function bindMomentumScroll(el){
 if(!el || el.dataset.momentumBound==='1')return;
 el.dataset.momentumBound='1';

 let pid=null,lastY=0,lastT=0,velocity=0,raf=0,dragging=false;
 let overscroll=0,springAnim=null;
 const target=()=>el.firstElementChild;
 const maxScroll=()=>Math.max(0,el.scrollHeight-el.clientHeight);

 const stopMomentum=()=>{ if(raf){cancelAnimationFrame(raf);raf=0} };

 const cancelSpring=()=>{
   if(springAnim){springAnim.cancel();springAnim=null}
   const t=target();
   if(t){t.style.transform='';t.classList.remove('rubber-band-active')}
   overscroll=0;
 };

 const rubberDistance=raw=>{
   const sign=Math.sign(raw), amount=Math.abs(raw);
   return sign*Math.min(76,76*(1-Math.exp(-amount/100)));
 };

 const paintRubber=()=>{
   const t=target(); if(!t)return;
   t.classList.add('rubber-band-active');
   t.style.transform=`translate3d(0,${rubberDistance(overscroll)}px,0)`;
 };

 const springBack=()=>{
   const t=target(); if(!t){overscroll=0;return}
   const current=rubberDistance(overscroll);
   if(Math.abs(current)<.5){t.style.transform='';t.classList.remove('rubber-band-active');overscroll=0;return}
   if(springAnim)springAnim.cancel();
   springAnim=t.animate(
     [
       {transform:`translate3d(0,${current}px,0)`,offset:0},
       {transform:`translate3d(0,${-current*.085}px,0)`,offset:.68},
       {transform:`translate3d(0,${current*.025}px,0)`,offset:.86},
       {transform:'translate3d(0,0,0)',offset:1}
     ],
     {duration:480,easing:'cubic-bezier(.2,.75,.22,1)'}
   );
   springAnim.onfinish=()=>{
     t.style.transform='';t.classList.remove('rubber-band-active');
     springAnim=null;overscroll=0;
   };
 };

 const startMomentum=()=>{
   stopMomentum();
   if(Math.abs(velocity)<0.03)return;
   let prev=performance.now();
   const tick=now=>{
     const dt=Math.min(32,Math.max(1,now-prev));prev=now;
     const max=maxScroll();
     const desired=el.scrollTop+velocity*dt;

     if(desired<0){
       el.scrollTop=0;
       overscroll=Math.min(28,Math.abs(velocity)*18);
       paintRubber();raf=0;springBack();return;
     }
     if(desired>max){
       el.scrollTop=max;
       overscroll=-Math.min(28,Math.abs(velocity)*18);
       paintRubber();raf=0;springBack();return;
     }

     el.scrollTop=desired;
     velocity*=Math.pow(.93,dt/16.67);
     if(Math.abs(velocity)>.015)raf=requestAnimationFrame(tick);
     else raf=0;
   };
   raf=requestAnimationFrame(tick);
 };

 let armed=false,startY0=0;
 el.addEventListener('pointerdown',e=>{
   if(e.target.closest('input,textarea'))return;
   stopMomentum();cancelSpring();
   pid=e.pointerId;lastY=startY0=e.clientY;lastT=performance.now();velocity=0;dragging=true;armed=false;
 });

 el.addEventListener('pointermove',e=>{
   if(!dragging||e.pointerId!==pid)return;
   if(!armed){
     if(Math.abs(e.clientY-startY0)<7)return;   /* a tap stays a tap; only a real drag scrolls */
     armed=true;lastY=e.clientY;lastT=performance.now();
     el.classList.add('momentum-dragging');el.setPointerCapture?.(pid);
     el.querySelectorAll('.is-pressed').forEach(x=>x.classList.remove('is-pressed'));
     return;
   }
   const now=performance.now();
   const dy=(e.clientY-lastY)/(window.__sy||1);
   const dt=Math.max(1,now-lastT);
   const max=maxScroll();

   if(overscroll!==0){
     const next=overscroll+dy;
     const crossed=(overscroll>0&&next<=0)||(overscroll<0&&next>=0);
     if(crossed){
       overscroll=0;
       const t=target();if(t)t.style.transform='';
       el.scrollTop=Math.max(0,Math.min(max,el.scrollTop-next));
     }else{
       overscroll=next;
       paintRubber();
     }
   }else{
     const desired=el.scrollTop-dy;
     if(desired<0){
       el.scrollTop=0;overscroll=-desired;paintRubber();
     }else if(desired>max){
       el.scrollTop=max;overscroll=-(desired-max);paintRubber();
     }else{
       el.scrollTop=desired;
     }
   }

   const instant=(-dy)/dt;
   velocity=velocity*.72+instant*.28;
   lastY=e.clientY;lastT=now;
   e.preventDefault();
 });

 const end=e=>{
   if(!dragging||e.pointerId!==pid)return;
   if(!armed){dragging=false;pid=null;return}
   armed=false;
   const kill=ev=>{ev.stopPropagation();ev.preventDefault()};el.addEventListener('click',kill,{capture:true,once:true});setTimeout(()=>el.removeEventListener('click',kill,{capture:true}),80);
   dragging=false;el.classList.remove('momentum-dragging');
   try{el.releasePointerCapture?.(pid)}catch(_){}
   pid=null;
   if(overscroll!==0)springBack();
   else startMomentum();
 };

 el.addEventListener('pointerup',end);
 el.addEventListener('pointercancel',end);

 el.addEventListener('wheel',e=>{
   stopMomentum();cancelSpring();
   el.scrollTop+=e.deltaY;
   e.preventDefault();
 },{passive:false});
}


