 [46,93,140,187,270,345].forEach((x,i)=>{const m=document.createElement('i');m.className=`carbon17-faint-marker ${i<3?'bad':'good'}`;m.style.left=`${x/390*100}%`;ticks.append(m)});gauge.append(ticks);
 const labels=document.createElement('div');labels.className='carbon17-gauge-labels';labels.innerHTML='<span>배출</span><span>0</span><span>절감</span>';gauge.append(labels);stage.append(gauge);

 const figureStage=document.createElement('div');figureStage.className='carbon17-figure-stage mascot-float-stage';stage.append(figureStage);
 function mascotSrc(i){ return `assets/carbon21/mascot_${files[i]}.png`; }
 function makeMascot(i, cls=''){ const el=img(mascotSrc(i),'carbon17-mascot-single '+cls); el.dataset.index=String(i); return el; }
 let current=makeMascot(active,'is-current'); figureStage.append(current);

 const status=document.createElement('div');status.className='carbon17-status';
 const step=document.createElement('span');step.className='carbon17-step';
 const value=document.createElement('strong');value.className='carbon17-value';
