 status.append(step,value,tail);stage.append(status);
 const pin=document.createElement('div');pin.className='carbon17-pin';stage.append(pin);

 const prev=document.createElement('button');prev.type='button';prev.className='carbon-arrow prev carbon17-arrow';prev.setAttribute('aria-label','이전 단계');prev.innerHTML='<span></span>';
 const next=document.createElement('button');next.type='button';next.className='carbon-arrow next carbon17-arrow';next.setAttribute('aria-label','다음 단계');next.innerHTML='<span></span>';
 stage.append(prev,next);

 const markerLayer=document.createElement('div');markerLayer.className='carbon17-marker-hits';
 stages.forEach((s,i)=>{const b=document.createElement('button');b.type='button';b.className='carbon17-marker-hit';b.setAttribute('aria-label',`${i+1}단계로 이동`);b.style.left=`${(s.marker-18)/390*100}%`;b.addEventListener('click',e=>{e.stopPropagation();transitionTo(i)});markerLayer.append(b)});stage.append(markerLayer);

 function paintStatus(i){
   const s=stages[i];step.textContent=s.step;value.textContent=s.value;
   status.classList.toggle('bad',s.tone==='bad');status.classList.toggle('good',s.tone==='good');
   const center=s.marker;const boxW=s.width;const left=s.left;
   status.style.left=`${left/390*100}%`;status.style.width=`${boxW/390*100}%`;
   const tailX=Math.max(18,Math.min(boxW-18,center-left));tail.style.left=`${tailX/boxW*100}%`;
   pin.style.left=`${center/390*100}%`;pin.classList.toggle('bad',s.tone==='bad');pin.classList.toggle('good',s.tone==='good');
   prev.hidden=i===0;next.hidden=i===5;
 }
 function finishTransition(nextEl,target){
   current?.remove(); current=nextEl; current.className='carbon17-mascot-single is-current';
   active=target; view.index=active; paintStatus(active); animating=false;
 }
 function transitionTo(target){
   target=Math.max(0,Math.min(5,target));
   if(animating || target===active) return;
   animating=true;
   const dir = target>active ? 1 : -1;
   const nextEl = makeMascot(target, dir>0 ? 'prep-right' : 'prep-left');
   figureStage.append(nextEl);
   // force layout before animating
   nextEl.getBoundingClientRect();
   current.classList.add(dir>0 ? 'leave-left' : 'leave-right');
   nextEl.classList.add('entering');
   nextEl.classList.remove('prep-right','prep-left');
   setTimeout(()=>finishTransition(nextEl,target), 340);
 }
 prev.addEventListener('click',e=>{e.stopPropagation(); if(active>0) transitionTo(active-1)});
