function openTeamChatOverlay(){
 clearTimers();
 if(stage.querySelector('.team-chat-overlay'))return;

 const page=document.createElement('div');
 page.className='team-chat-overlay';
 page.style.transform='translate3d(100%,0,0)';

 page.append(img('assets/screens/341_chat_clean.png','full-screen team-chat-bg'));

 const log=document.createElement('div');log.className='chat-log';
 chatLogs.team.forEach(m=>{const b=document.createElement('div');b.className='chat-msg';b.textContent=m;log.append(b)});
 page.append(log);

 const input=document.createElement('input');input.className='chat-input';input.placeholder='메시지를 입력하세요';
 input.addEventListener('keydown',e=>{
   if(e.key==='Enter'&&input.value.trim()){
     chatLogs.team.push(input.value.trim());
     const b=document.createElement('div');b.className='chat-msg';b.textContent=input.value.trim();log.append(b);
     input.value='';log.scrollTop=log.scrollHeight;
   }
 });
 page.append(input);

 const backHit=makeTap(8,45,85,70,()=>closeTeamChatOverlay(page));
 backHit.classList.add('team-chat-back');
 page.append(backHit);

 stage.append(page);

 // Smart transition: RIGHT outside -> center.
 requestAnimationFrame(()=>requestAnimationFrame(()=>{
   const entrance=page.animate(
     [{transform:'translate3d(100%,0,0)'},{transform:'translate3d(0,0,0)'}],
     {duration:360,easing:'cubic-bezier(.22,.82,.22,1)',fill:'forwards'}
   );
   entrance.onfinish=()=>{page.style.transform='translate3d(0,0,0)';entrance.cancel()};
 }));

 let swipeId=null,swipeStart=0,swipeLast=0;
 page.addEventListener('pointerdown',e=>{
   if(e.target.closest('input,button'))return;
   swipeId=e.pointerId;swipeStart=swipeLast=e.clientX;page.setPointerCapture?.(swipeId);
 });
 page.addEventListener('pointermove',e=>{
   if(e.pointerId!==swipeId)return;
   swipeLast=e.clientX;const dx=Math.max(0,e.clientX-swipeStart);
   if(dx>0)page.style.transform=`translate3d(${Math.min(120,dx*.72)}px,0,0)`;
 });
 const finishSwipe=e=>{
   if(e.pointerId!==swipeId)return;
   const dx=(swipeLast||e.clientX)-swipeStart;
   try{page.releasePointerCapture?.(swipeId)}catch(_){}
   swipeId=null;
   if(dx>70)closeTeamChatOverlay(page);
   else page.animate([{transform:page.style.transform||'translate3d(0,0,0)'},{transform:'translate3d(0,0,0)'}],{duration:220,easing:'cubic-bezier(.2,.8,.2,1)',fill:'forwards'}).onfinish=()=>{page.style.transform='translate3d(0,0,0)'};
 };
 page.addEventListener('pointerup',finishSwipe);page.addEventListener('pointercancel',finishSwipe);
}

function closeTeamChatOverlay(page){
 if(!page || page.dataset.closing==='1')return;
 page.dataset.closing='1';

 // Guaranteed smart transition: center -> RIGHT outside.
 const a=page.animate(
   [{transform:'translate3d(0,0,0)'},{transform:'translate3d(100%,0,0)'}],
   {duration:360,easing:'cubic-bezier(.3,.02,.72,.2)',fill:'forwards'}
 );
 a.onfinish=()=>page.remove();
}

