 const listVp=document.createElement('div');listVp.className='esg-list-viewport';
 const list=document.createElement('div');list.className='esg-list';listVp.append(list);root.append(listVp);bindMomentumScroll(listVp);
 function buildList(t,dir=0){
   list.innerHTML='';list.classList.remove('swap-left','swap-right');
   itemSets[t].forEach((it,idx)=>{
     const [company,desc,state,count,p,liked]=it;
     const card=document.createElement('div');card.className='esg-post-card';card.style.setProperty('--delay',`${Math.min(idx,7)*28}ms`);
     const heart=document.createElement('button');heart.type='button';heart.className=`esg-heart${liked?' liked':''}`;heart.setAttribute('aria-label','좋아요');heart.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20.6 10.55 19.3C5.4 14.7 2 11.65 2 7.9 2 4.85 4.42 2.5 7.5 2.5c1.74 0 3.41.81 4.5 2.08A6.02 6.02 0 0 1 16.5 2.5C19.58 2.5 22 4.85 22 7.9c0 3.75-3.4 6.8-8.55 11.4L12 20.6Z"/></svg>';
     heart.addEventListener('click',e=>{e.stopPropagation();heart.classList.toggle('liked');heart.classList.remove('heart-pop');void heart.offsetWidth;heart.classList.add('heart-pop');setTimeout(()=>heart.classList.remove('heart-pop'),320)});
     const title=document.createElement('strong');title.className='esg-company';title.textContent=company;
     const body=document.createElement('p');body.className='esg-desc';body.textContent=desc;
     const foot=document.createElement('div');foot.className='esg-foot';const stateEl=document.createElement('span');stateEl.className='esg-state';stateEl.textContent=state;
     const bar=document.createElement('i');bar.className='esg-progress';const fill=document.createElement('b');fill.style.width=`${Math.max(0,Math.min(1,p))*100}%`;bar.append(fill);
     const countEl=document.createElement('span');countEl.className='esg-count';countEl.textContent=count;foot.append(stateEl,bar,countEl);card.append(title,heart,body,foot);list.append(card)
   });
   listVp.scrollTop=0;
   if(dir){void list.offsetWidth;list.classList.add(dir>0?'swap-left':'swap-right')}
 }
 buildList(currentTab,0);

 const order={all:0,progress:1,mine:2};
