function tapAt(x,y,w,h,fn,cls='',parent=null){const b=makeTap(x,y,w,h,fn,'x-tap '+cls);(parent||stage).append(b);return b}
function enableTapThrough(vp,selector,handler){
 let sx=0,sy=0,st=0;
 vp.addEventListener('pointerdown',e=>{sx=e.clientX;sy=e.clientY;st=Date.now()},true);
 vp.addEventListener('pointerup',e=>{
   if(Math.hypot(e.clientX-sx,e.clientY-sy)>8||Date.now()-st>650)return;
   const t=document.elementFromPoint(e.clientX,e.clientY);if(!t||t.closest('button,input,textarea,a'))return;
   const c=t.closest(selector);if(c&&vp.contains(c))handler(c);
 });
}
function dim(cls){const d=el('div','modal-dim x-dim '+(cls||''));d.addEventListener('click',e=>{if(e.target===d)closeDim(d)});overlay.append(d);return d}
