function actionSheet(title,options){
 const d=dim('x-sheet-dim');const s=el('div','x-sheet');
 if(title)s.append(el('div','x-sheet-title',title));
 options.forEach(o=>{const b=el('button','x-sheet-btn'+(o.danger?' danger':'')+(o.on?' on':''),o.label);b.type='button';
   b.addEventListener('click',()=>{closeDim(d);setTimeout(()=>o.fn&&o.fn(),120)});s.append(b)});
 const c=el('button','x-sheet-btn cancel','취소');c.type='button';c.addEventListener('click',()=>closeDim(d));s.append(c);
 d.append(s);
}
