function sortEsg(mode){
 const list=stage.querySelector('.esg-list');if(!list)return;
 const cards=[...list.children];const n=c=>{const t=c.querySelector('.esg-count')?.textContent||'';return parseInt(t.replace(/[^0-9/]/g,'').split('/')[0]||'0',10)};
 if(mode==='like')cards.sort((a,b)=>n(b)-n(a));
 if(mode==='close')cards.sort((a,b)=>{const ra=n(a)>=1000?-1:n(a),rb=n(b)>=1000?-1:n(b);return rb-ra});
 if(mode==='new')cards.sort((a,b)=>(+a.dataset.o)-(+b.dataset.o));
 cards.forEach(c=>list.append(c));stage.querySelector('.esg-list-viewport').scrollTop=0;
}

