/* points filter/search */
function filterPoints(mode,q=''){
 const L=stage.querySelector('.pl');if(!L)return;let lastDate=null,shown=0;
 [...L.children].forEach(c=>{
   if(c.classList.contains('pl-date')){if(lastDate)lastDate.style.display=shown?'':'none';lastDate=c;shown=0;return}
   if(!c.classList.contains('pl-row'))return;
   const plus=!!c.querySelector('.plus');const txt=c.textContent;
   const vis=(mode==='all'||(mode==='plus'&&plus)||(mode==='minus'&&!plus))&&(!q||txt.includes(q));
   c.style.display=vis?'':'none';if(vis)shown++;
 });
 if(lastDate)lastDate.style.display=shown?'':'none';
}

